import React, { useCallback, useMemo, useState } from 'react';

import {
  buildVisibleRows,
  DrillDownTable,
  mapWatchtowerApiColumnGroups,
  WATCHTOWER_TABLE_API_MOCK,
  WATCHTOWER_TABLE_COMPARE_MOCK,
} from 'components/DrillDownTable';
import type { DrillDownRow } from 'components/DrillDownTable';

import {
  DRILL_DOWN_TREE,
  type DrillDownNode,
} from './DrillDownTableExample.mock';
import {
  Badge,
  Container,
  MetaRow,
  SectionGroup,
} from './DrillDownTableExample.styles';

function toRow(node: DrillDownNode, showEfficiencies: boolean): DrillDownRow {
  return {
    id: node.id,
    parentId: node.parentId,
    level: node.level,
    hasChildren: node.hasChildren,
    label: node.label,
    logoSrc: node.brandLogoSrc,
    cells: {
      impact_pre_period: { value: node.impactPrePeriod },
      impact_delta: { value: node.impactDelta },
      impact_growth_rate: {
        value: node.impactGrowthRate,
        type: node.impactGrowthRate === null ? 'empty' : 'positive',
      },
      impact_post_period: {
        value:
          node.impactPostPeriod === null ? null : `${node.impactPostPeriod}%`,
        type: node.impactPostPeriod === null ? 'empty' : 'positive',
      },
      input_pre_period: { value: node.inputPrePeriod },
      input_post_period: { value: node.inputPostPeriod },
      input_delta: {
        value: node.inputDelta,
        type: node.inputDelta === null ? 'empty' : 'positive',
      },
      ...(showEfficiencies
        ? {
            maco_roi_pre_period: { value: node.macoPrePeriod },
            maco_roi_post_period: { value: node.macoPostPeriod },
            maco_roi_delta: {
              value: node.macoDelta,
              type: node.macoDelta === null ? 'empty' : 'positive',
            },
          }
        : {}),
    },
  };
}

const BASE_COLUMN_GROUPS = mapWatchtowerApiColumnGroups(
  WATCHTOWER_TABLE_API_MOCK.column_groups,
);

const COMPARE_COLUMN_GROUPS = mapWatchtowerApiColumnGroups(
  WATCHTOWER_TABLE_COMPARE_MOCK.column_groups,
);

export const DrillDownTableExample: React.FC = () => {
  const [expandedNodes, setExpandedNodes] = useState<Set<string>>(new Set());
  const [showEfficiencies, setShowEfficiencies] = useState(false);

  const toggleNode = useCallback((id: string) => {
    setExpandedNodes((prev) => {
      const next = new Set(prev);
      if (next.has(id)) {
        next.delete(id);
      } else {
        next.add(id);
      }
      return next;
    });
  }, []);

  const visibleNodes = useMemo(
    () => buildVisibleRows(DRILL_DOWN_TREE, expandedNodes),
    [expandedNodes],
  );

  const rows: DrillDownRow[] = useMemo(
    () => visibleNodes.map((n) => toRow(n, showEfficiencies)),
    [visibleNodes, showEfficiencies],
  );

  const columnGroups = useMemo(
    () => (showEfficiencies ? COMPARE_COLUMN_GROUPS : BASE_COLUMN_GROUPS),
    [showEfficiencies],
  );

  return (
    <Container>
      <SectionGroup>
        <h3
          style={{
            margin: 0,
            fontFamily: 'Work Sans, sans-serif',
            fontSize: 20,
            fontWeight: 600,
          }}
        >
          DrillDownTable (Watchtower Pattern)
        </h3>
        <MetaRow>
          <Badge variant="info">Prototype</Badge>
          <Badge variant="neutral">DrillDown in Country Level</Badge>
        </MetaRow>
      </SectionGroup>

      <SectionGroup>
        <DrillDownTable
          title="Table"
          unit="[ k hl ]"
          columnGroups={columnGroups}
          rows={rows}
          axisWidth="220px"
          expandedIds={expandedNodes}
          onToggleRow={toggleNode}
          compareLabel="Compare Efficiencies"
          compareTooltip={WATCHTOWER_TABLE_API_MOCK.compare_tooltip}
          compareChecked={showEfficiencies}
          onCompareChange={setShowEfficiencies}
          dataTestId="watchtower-drill-down-table"
        />
      </SectionGroup>
    </Container>
  );
};
